import{_ as a,c as e,o as t,a2 as n}from"./chunks/framework.mqLGQ42V.js";const h=JSON.parse(`{"title":"裁剪 (Clipping) - Rive 编辑器","description":"操控形状 (Manipulating Shapes) 裁剪 (Clipping) 允许你用一个形状的轮廓来'切除'或'遮罩'另一个形状。","frontmatter":{"title":"裁剪 (Clipping) - Rive 编辑器","description":"操控形状 (Manipulating Shapes) 裁剪 (Clipping) 允许你用一个形状的轮廓来'切除'或'遮罩'另一个形状。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 形状操控, 裁剪"}]]},"headers":[],"relativePath":"editor/manipulating-shapes/clipping.md","filePath":"editor/manipulating-shapes/clipping.md","lastUpdated":1774838907000}`),p={name:"editor/manipulating-shapes/clipping.md"};function o(l,i,r,s,g,c){return t(),e("div",null,[...i[0]||(i[0]=[n('<p>操控形状 (Manipulating Shapes)</p><h1 id="裁剪-clipping" tabindex="-1">裁剪 (Clipping) <a class="header-anchor" href="#裁剪-clipping" aria-label="Permalink to &quot;裁剪 (Clipping)&quot;">​</a></h1><p>裁剪 (Clipping) 允许你用一个形状的轮廓来&quot;切除&quot;或&quot;遮罩&quot;另一个形状。</p><h2 id="​-裁剪的工作原理" tabindex="-1"><a href="#how-clipping-works">​</a> 裁剪的工作原理 <a class="header-anchor" href="#​-裁剪的工作原理" aria-label="Permalink to &quot;[​](#how-clipping-works) 裁剪的工作原理&quot;">​</a></h2><p>当你将一个对象设置为另一个对象的&quot;裁剪源 (Clipper)&quot;时，只有裁剪源覆盖的区域内的内容才会被渲染。这与图形软件中的&quot;遮罩 (Mask)&quot;概念类似。</p><p>例如：</p><ul><li>将一个<strong>圆形</strong>设为<strong>图片</strong>的裁剪源，图片就会呈现为圆形头像。</li><li>将一个<strong>窗户形状</strong>设为<strong>背景</strong>的裁剪源，可以创建透过窗户看外面的视觉效果。</li></ul><h2 id="​-设置裁剪" tabindex="-1"><a href="#setting-up-clipping">​</a> 设置裁剪 <a class="header-anchor" href="#​-设置裁剪" aria-label="Permalink to &quot;[​](#setting-up-clipping) 设置裁剪&quot;">​</a></h2><ol><li>选中被裁剪的对象（即你要显示的内容）。</li><li>在 <a href="/docs/editor/interface-overview/inspector">检查器 (Inspector)</a> 中找到 <strong>Clipping</strong> 选项。</li><li>点击加号，选择作为裁剪源的形状。</li></ol><p>裁剪源可以是任何矢量形状，包括程序化图形和自定义路径。</p><h2 id="​-反向裁剪-inverted-clipping" tabindex="-1"><a href="#inverted-clipping">​</a> 反向裁剪 (Inverted Clipping) <a class="header-anchor" href="#​-反向裁剪-inverted-clipping" aria-label="Permalink to &quot;[​](#inverted-clipping) 反向裁剪 (Inverted Clipping)&quot;">​</a></h2><p>默认情况下，裁剪只显示裁剪源<strong>内部</strong>的区域。如果你希望只显示裁剪源<strong>外部</strong>的区域，可以在裁剪设置中启用&quot;反向 (Invert)&quot;选项。</p><p>这对于创建&quot;挖孔&quot;效果非常有用（例如：在地面上挖出一个洞，露出下方的隐藏内容）。</p><h2 id="​-动画化裁剪" tabindex="-1"><a href="#animating-clips">​</a> 动画化裁剪 <a class="header-anchor" href="#​-动画化裁剪" aria-label="Permalink to &quot;[​](#animating-clips) 动画化裁剪&quot;">​</a></h2><p>裁剪源形状本身可以像其他形状一样进行动画化。通过动画化裁剪源的位置、缩放或顶点，你可以创建动态的遮罩效果，如：</p><ul><li>进度条填充</li><li>角色从门后走出</li><li>聚光灯跟随移动</li></ul><p><a href="/docs/editor/manipulating-shapes/bones">骨骼 (Bones)</a><a href="/docs/editor/manipulating-shapes/solos">单独显示 (Solos)</a></p>',17)])])}const u=a(p,[["render",o]]);export{h as __pageData,u as default};
